<button type="button" class="ces-sidebar-toggle" x-data="{}" x-on:click="$store.sidebar.isOpen ? $store.sidebar.close() : $store.sidebar.open()" x-bind:aria-expanded="$store.sidebar.isOpen" x-bind:aria-label="$store.sidebar.isOpen ? 'Tutup sidebar' : 'Buka sidebar'" aria-controls="fi-main-sidebar" @if($collapsed ?? false) x-show="! $store.sidebar.isOpen" x-cloak @endif><span aria-hidden="true" class="ces-sidebar-symbol"></span></button>
